bool wordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = Set<String>.from(wordDict);
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  return dp[s.length];
}

int minWordBreaks(String s, List<String> wordDict) {
  if (s.isEmpty) return 0;
  Set<String> wordSet = Set<String>.from(wordDict);
  List<int> dp = List<int>.filled(s.length + 1, 999999);
  List<List<String>> parent = List.generate(s.length + 1, (_) => []);

  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] != 999999 && wordSet.contains(s.substring(j, i))) {
        if (dp[j] + 1 < dp[i]) {
          dp[i] = dp[j] + 1;
          parent[i] = [for (var seg in parent[j]) seg];
          parent[i].add(s.substring(j, i));
        }
      }
    }
  }

  return dp[s.length];
}

List<List<String>> wordBreakII(String s, List<String> wordDict) {
  List<String> wordList = List<String>.from(wordDict);
  Set<String> wordSet = Set<String>.from(wordDict);
  List<List<List<String>>> memo = List.generate(s.length + 1, (_) => []);

  List<List<String>> backtrack(int index) {
    if (index == s.length) {
      return [[]];
    }
    if (memo[index].isNotEmpty) {
      return memo[index];
    }

    List<List<String>> result = [];
    for (String word in wordList) {
      if (wordSet.contains(word) && s.startsWith(word, index)) {
        int nextIndex = index + word.length;
        for (var segment in backtrack(nextIndex)) {
          result.add([word, ...segment]);
        }
      }
    }
    memo[index] = result;
    return result;
  }

  return backtrack(0);
}

