int fn0(List<int> signalDays, int cycleDays) {
  if (cycleDays <= 0) return 0;
  final Map<int, int> counts = {};
  for (final day in signalDays) {
    final remainder = day % cycleDays;
    counts[remainder] = (counts[remainder] ?? 0) + 1;
  }
  int bestGap = cycleDays;
  int prevDay = -1;
  counts.forEach((day, _count) {
    if (prevDay != -1) {
      final gap = day - prevDay;
      if (gap < bestGap) bestGap = gap;
    }
    prevDay = day;
  });
  if (prevDay != -1 && prevDay < cycleDays) {
    final gap = cycleDays - prevDay;
    if (gap < bestGap) bestGap = gap;
  }
  return bestGap;
}

