  int left = 0;
  int right = sortedDurations.length - 1;
  int best = -1;
  while (left <= right) {
    int total = 0;
    int end = right;
    for (int start = left; start <= end; start++) {
      total += sortedDurations[start];
      if (total > maxTotal) {
        end = start - 1;
        break;
