Set<int> fn0(List<List<int>> passes, int startDay, int endDay) {
  if (passes.isEmpty || startDay >= endDay) {
    return <int>{};
  }

  Map<int, int> totalMinutes = <int, int>{};
  for (List<int> pass in passes) {
    int day = pass[0];
    int start = pass[1];
    int end = pass[2];
    int duration = end - start;

    if (day < startDay || day > endDay || duration <= 0) {
      continue;
    }

    if (start < startDay) {
      start = startDay;
    }

    if (end > endDay) {
      end = endDay;
    }

    for (int m = start; m <= end; m++) {
      totalMinutes[m] = (totalMinutes[m] ?? 0) + duration;
    }
  }

  int maxMinutes = 0;
  Set<int> bestDays = <int>{};

  totalMinutes.forEach((int day, int minutes) {
    if (minutes > maxMinutes) {
      maxMinutes = minutes;
      bestDays = <int>{day};
    } else if (minutes == maxMinutes) {
      bestDays.add(day);
    }
  });

  return bestDays;
}

