    int p2X = samples[i+1][0], p2Y = samples[i+1][1];
    int p3X = samples[i+2][0], p3Y = samples[i+2][1];
    int area = (p1X * (p2Y - p3Y) + p2X * (p3Y - p1Y) + p3X * (p1Y - p2Y)).abs();
    if (area == 0) return false;
  }
  return true;
}

