Set<int> fn0(List<int> playlist, int maxEnergy) {
  if (playlist.isEmpty) return <int>{};
  Set<int> result = <int>{};
  int left = 0;
  int currentEnergy = 0;
  for (int right = 0; right < playlist.length; right++) {
    currentEnergy += playlist[right];
    while (currentEnergy > maxEnergy && left <= right) {
      currentEnergy -= playlist[left];
      left++;
