List<int> fn0(List<int> cycleDurations, int totalSeconds) {
  if (cycleDurations.isEmpty || totalSeconds < 0) {
    return <int>[];
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  int lcm(int a, int b) {
    return a * b ~/ gcd(a, b);
  }

  int common = cycleDurations[0];
  for (int i = 1; i < cycleDurations.length; i++) {
    common = lcm(common, cycleDurations[i]);
  }

  if (common == 0) {
    return <int>[];
  }

  List<int> remainders = <int>[];
  for (int duration in cycleDurations) {
    remainders.add(totalSeconds % duration);
  }

  int sum = 0;
  for (int r in remainders) {
    sum += r;
  }

  return <int>[common, sum];
}

