List<int> fn0(List<List<int>> grid, int targetSum) {
  int rows = grid.length;
  if (rows == 0) return [];
  int cols = grid[0].length;
  if (cols == 0) return [];
  List<int> result = [];
  int left = 0;
  int right = cols - 1;
  while (left <= right) {
    int mid = (left + right) >> 1;
    int sum = 0;
    for (int r = 0; r < rows; r++) {
      sum += grid[r][mid];
    }
    if (sum == targetSum) {
      result.add(mid);
      int temp = mid - 1;
      left = mid + 1;
      right = mid - 1;
      while (left <= right) {
        int m = (left + right) >> 1;
        int s = 0;
        for (int rr = 0; rr < rows; rr++) {
          s += grid[rr][m];
        }
        if (s == targetSum) {
          result.add(m);
          temp = m - 1;
          left = m + 1;
          right = m - 1;
        } else if (s < targetSum) {
          left = m + 1;
        } else {
          right = m - 1;
        }
      }
      left = temp + 1;
      right = cols - 1;
    } else if (sum < targetSum) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  result.sort();
  return result;
}

