int combinations(int n, int k) {
  if (k > n) return 0;
  if (k == 0 || k == n) return 1;
  if (k == n - k) return combinations(n, n - k);
  int result = 1;
  for (int i = 0; i < k; i++) {
    result = result * (n - i) ~/ (i + 1);
  }
  return result;
}

