bool fn0(List<int> cycleUnits, int totalMinutes) {
  if (totalMinutes < 0) return false;
  if (cycleUnits.isEmpty) return totalMinutes == 0;

  const int mod = 1000000007;

  List<int> dp = List.filled(totalMinutes + 1, 0);
  dp[0] = 1;
  for (int unit in cycleUnits) {
    if (unit <= 0) continue;
    for (int t = unit; t <= totalMinutes; t++) {
      int sum = 0;
      for (int k = 1; k <= unit; k++) {
        int prev = (t - k) >= 0 ? dp[t - k] : 0;
        sum = (sum + prev) % mod;
      }
      dp[t] = (dp[t] + sum) % mod;
    }
  }
  return dp[totalMinutes] % mod == 0;
}

