        if (prevDay > 0 && schedule[prevDay - 1] != schedule[i]) {
          cost = (prevDay - day).abs();
        }
        int cur = cost + dp[i][day - prevDay];
        if (cur > best) {
          best = cur;
          bestPrev = prevDay;
        }
      }
      dp[i][day] = best;
      prev[i][day] = bestPrev;
    }
  }
  int bestTotal = 0;
  int bestStart = -1;
  for (int s = startDay; s < n; s++) {
    for (int day = 0; day <= endDay; day++) {
      int cur = dp[s][day];
      if (cur > bestTotal) {
        bestTotal = cur;
        bestStart = s;
      }
    }
  }
  if (bestStart == -1 || bestTotal > maxSkip) return -1;
  int last = 0;
  int prevDay = endDay;
  for (int i = bestStart; i < n; i++) {
    int pd = prev[bestStart][endDay];
    if (pd == -1) return -1;
    last = schedule[i];
    prevDay = pd;
  }
  return last - schedule[bestStart];
}

