  int lo = 0, hi = n - 1;
  while (lo < hi) {
    int mid = (lo + hi) >> 1;
    if (fn0(pixels, threshold)[1] == mid + 1) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return [total, lo];
}

