Set<int> fn0(List<int> samples, int minDuration, int maxGap, int maxCount) {
  Map<int, int> freq = {};
  Map<int, int> startIdx = {};
  Map<int, int> endIdx = {};
  int left = 0;
  int bestStart = -1;
  int bestEnd = -1;
  int bestLen = 0;
  int longestRun = 0;
  int longestRunStart = -1;
  int longestRunEnd = -1;

  for (int right = 0; right < samples.length; right++) {
    int temp = samples[right];
    freq[temp] = (freq[temp] ?? 0) + 1;
    startIdx[temp] = startIdx[temp] ?? left;
    if (freq[temp]! > longestRun) {
      longestRun = freq[temp]!;
      longestRunStart = startIdx[temp]!;
      longestRunEnd = right;
    }

    while ((right - left + 1) > maxCount || (right - (startIdx[temp] ?? left) + 1) > maxDuration || 
           (left > 0 && (startIdx[samples[left]] ?? 0) - (endIdx[samples[left - 1]] ?? left - 1) > maxGap)) {
      int removed = samples[left];
      freq[removed] = freq[removed]! - 1;
      if (freq[removed] == 0) {
        freq.remove(removed);
      }
      if (left == longestRunStart && freq[removed]! < longestRun) {
        longestRun = 0;
        longestRunStart = -1;
        longestRunEnd = -1;
      }
      endIdx[removed] = endIdx[removed] ?? right;
      left++;
    }

    if (freq.length >= minDuration) {
      if (right - left + 1 > bestLen) {
        bestLen = right - left + 1;
        bestStart = left;
        bestEnd = right;
      }
    }
  }

  if (bestLen == 0) {
    return longestRun > 0 ? {longestRunStart, longestRunEnd} : {};
  }

  Set<int> bestFreq = {};
  for (int i = bestStart; i <= bestEnd; i++) {
    bestFreq.add(samples[i]);
  }
  return bestFreq;
}

