bool fn0(List<int> rolls) {
  int n = rolls.length;
  if (n % 2 != 0) return false;
  List<int> dp = List.filled(n, 0);
  dp[0] = rolls[0];
  dp[1] = rolls[0] + rolls[1];
  for (int i = 2; i < n; i++) {
    int prev1 = dp[i - 1];
    int prev2 = dp[i - 2];
    int current = rolls[i];
    int option1 = prev2 + current;
    int option2 = prev1 + current - rolls[i - 2];
    dp[i] = option1 > option2 ? option1 : option2;
  }
  return dp[n - 1] % 2 == 0;
}

