    if (row == n) {
      solutions.add(List.from(queens));
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(queens, row, col)) {
        queens[row] = col;
        solve(row + 1, queens);
      }
    }
  }

  var queens = List<int>.filled(n, -1);
  solve(0, queens);

  print('Solving N-Queens for N=$n');
