class Quaternion {
  final double w, x, y, z;

  const Quaternion(this.w, this.x, this.y, this.z);

  factory Quaternion.fromEuler(double yaw, double pitch, double roll) {
    double cy = cos(yaw / 2);
    double sy = sin(yaw / 2);
    double cp = cos(pitch / 2);
    double sp = sin(pitch / 2);
    double cr = cos(roll / 2);
    double sr = sin(roll / 2);

    double w = cr * cy * cp + sr * sy * sp;
    double x = sr * cy * cp - cr * sy * sp;
    double y = cr * sy * cp + sr * cy * sp;
    double z = cr * cy * sp - sr * sy * cp;

    return Quaternion(w, x, y, z);
  }

  double norm() => w * w + x * x + y * y + z * z;

  Quaternion normalized() {
    double n = sqrt(norm());
    return n == 0 ? this : Quaternion(w / n, x / n, y / n, z / n);
  }

  Quaternion conjugate() => Quaternion(w, -x, -y, -z);

  Quaternion operator +(Quaternion other) =>
      Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  Quaternion operator -(Quaternion other) =>
      Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

  Quaternion operator *(double scalar) =>
      Quaternion(w * scalar, x * scalar, y * scalar, z * scalar);

  Quaternion operator *(Quaternion other) {
    double nw = w * other.w - x * other.x - y * other.y - z * other.z;
    double nx = w * other.x + x * other.w + y * other.z - z * other.y;
    double ny = w * other.y - x * other.z + y * other.w + z * other.x;
    double nz = w * other.z + x * other.y - y * other.x + z * other.w;
    return Quaternion(nw, nx, ny, nz);
  }

  Quaternion rotated(Quaternion rotation) => rotation * this * rotation.conjugate();

  void print() {
    print('Quaternion($w, $x, $y, $z)');
  }
}

