/// A Quaternion represents a 3D rotation and can be used to interpolate between orientations.
/// Quaternions are represented with four components: w, x, y, z.
class Quaternion {
  double w;
  double x;
  double y;
  double z;

  Quaternion(this.w, this.x, this.y, this.z);

  /// Creates a unit quaternion representing a rotation of θ radians around the axis defined by the unit vector (x, y, z).
  static Quaternion fromAxisAngle(double angle, double x, double y, double z) {
    double halfAngle = angle / 2;
    double sinHalf = sin(halfAngle);
    return Quaternion(
      cos(halfAngle),
      x * sinHalf,
      y * sinHalf,
      z * sinHalf,
    );
  }

  double norm() => w * w + x * x + y * y + z * z;

  bool isUnit() => norm().abs() == 1.0;

  Quaternion normalized() {
    double n = norm();
    if (n == 0) {
      return Quaternion(1.0, 0.0, 0.0, 0.0);
    }
    return Quaternion(w / n, x / n, y / n, z / n);
  }

  Quaternion conjugate() => Quaternion(w, -x, -y, -z);

  Quaternion inverse() {
    return conjugate().normalized() * (1.0 / norm());
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      w + other.w,
      x + other.x,
      y + other.y,
      z + other.z,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      w - other.w,
      x - other.x,
      y - other.y,
      z - other.z,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(w * scalar, x * scalar, y * scalar, z * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double w1 = w, x1 = x, y1 = y, z1 = z;
    double w2 = other.w, x2 = other.x, y2 = other.y, z2 = other.z;

    double w = w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2;
    double x = w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2;
    double y = w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2;
    double z = w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2;

    return Quaternion(w, x, y, z);
  }

  @override
  String toString() => '($w, $x, $y, $z)';
}

