    double halfAngle = angle * 0.5;
    double sinHalf = sin(halfAngle);
    double norm = sqrt(axis.x * axis.x + axis.y * axis.y + axis.z * axis.z);
    double invNorm = 1.0 / norm;
    return Quaternion(
      cos(halfAngle),
      axis.x * sinHalf * invNorm,
      axis.y * sinHalf * invNorm,
      axis.z * sinHalf * invNorm,
    );
  }

  factory Quaternion.fromEuler(double yaw, double pitch, double roll) {
    double cy = cos(yaw * 0.5), sy = sin(yaw * 0.5);
    double cp = cos(pitch * 0.5), sp = sin(pitch * 0.5);
    double cr = cos(roll * 0.5), sr = sin(roll * 0.5);

    double qw = cy * cp * cr + sy * sp * sr;
    double qx = cy * cp * sr - sy * sp * cr;
    double qy = cy * sp * cr + sy * cp * sr;
    double qz = sy * cp * cr - cy * sp * sr;
    return Quaternion(qw, qx, qy, qz);
  }

  double norm() => w * w + x * x + y * y + z * z;

  Quaternion normalized() {
    double n = sqrt(norm());
    return n == 0 ? this : Quaternion(w / n, x / n, y / n, z / n);
  }

  Quaternion conjugate() => Quaternion(w, -x, -y, -z);

  Quaternion inverse() => conjugate().normalized() * (1 / norm());

  Quaternion operator *(Quaternion other) {
    double nw = w * other.w - x * other.x - y * other.y - z * other.z;
    double nx = w * other.x + x * other.w + y * other.z - z * other.y;
    double ny = w * other.y - x * other.z + y * other.w + z * other.x;
    double nz = w * other.z + x * other.y - y * other.x + z * other.w;
    return Quaternion(nw, nx, ny, nz);
  }

  Quaternion operator +(Quaternion other) =>
      Quaternion(w + other.w, x + other.x, y + other.y, z + other.z);

  Quaternion operator -(Quaternion other) =>
      Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);

