class Quaternion {
  final double w;
  final double x;
  final double y;
  final double z;

  const Quaternion(this.w, this.x, this.y, this.z);

  factory Quaternion.fromEuler(double roll, double pitch, double yaw) {
    double qw = cos(roll / 2) * cos(pitch / 2) * cos(yaw / 2) +
        sin(roll / 2) * sin(pitch / 2) * sin(yaw / 2);
    double qx = sin(roll / 2) * cos(pitch / 2) * cos(yaw / 2) -
        cos(roll / 2) * sin(pitch / 2) * sin(yaw / 2);
    double qy = cos(roll / 2) * sin(pitch / 2) * cos(yaw / 2) +
        sin(roll / 2) * cos(pitch / 2) * sin(yaw / 2);
    double qz = cos(roll / 2) * cos(pitch / 2) * sin(yaw / 2) -
        sin(roll / 2) * sin(pitch / 2) * cos(yaw / 2);
    return Quaternion(qw, qx, qy, qz);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      w + other.w,
      x + other.x,
      y + other.y,
      z + other.z,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      w - other.w,
      x - other.x,
      y - other.y,
      z - other.z,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      w * scalar,
      x * scalar,
      y * scalar,
      z * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    double nw = w * other.w - x * other.x - y * other.y - z * other.z;
    double nx = w * other.x + x * other.w + y * other.z - z * other.y;
    double ny = w * other.y - x * other.z + y * other.w + z * other.x;
    double nz = w * other.z + x * other.y - y * other.x + z * other.w;
    return Quaternion(nw, nx, ny, nz);
  }

  double norm() {
    return sqrt(pow(w, 2) + pow(x, 2) + pow(y, 2) + pow(z, 2));
  }

  Quaternion normalize() {
    double n = norm();
    return n == 0
        ? this
        : Quaternion(w / n, x / n, y / n, z / n);
  }

  Quaternion conjugate() {
    return Quaternion(w, -x, -y, -z);
  }

  Quaternion inverse() {
    return conjugate() * (1 / norm());
  }

  @override
  String toString() {
    return 'Quaternion($w, $x, $y, $z)';
  }
}

