int fn0(int startDay, int duration, int maxGap) {
  if (duration <= 0) {
    return 0;
  }

  final int gcd = _gcd(startDay, duration);
  final int reducedStart = startDay ~/ gcd;
  final int reducedDuration = duration ~/ gcd;

  final Map<int, int> cyclePrimeCounts = <int, int>{};
  final Set<int> cyclePrimes = <int>{};

  for (int i = 1; i < reducedDuration; i++) {
    final int day = (reducedStart * i) % reducedDuration;
    if (day == 0) {
      continue;
    }

    if (_isPrime(day)) {
      cyclePrimes.add(day);
    }
  }

  for (final int p in cyclePrimes) {
    int count = 0;
    for (int i = 1; i < reducedDuration; i++) {
      if ((reducedStart * i) % reducedDuration == p) {
        count++;
      }
    }
    cyclePrimeCounts[p] = count;
  }

  if (cyclePrimeCounts.isEmpty) {
    return 0;
  }

  int result = 0;

  void _backtrack(int index, int currentGcd) {
    if (index == cyclePrimeCounts.length) {
      if (currentGcd <= maxGap) {
        result++;
      }
      return;
    }

    final int prime = cyclePrimeCounts.keys.elementAt(index);
    final int count = cyclePrimeCounts[prime]!;
    int nextGcd = _gcd(currentGcd, count);

    for (int k = 0; k <= count; k++) {
      _backtrack(index + 1, nextGcd);
      if (nextGcd == 1) {
        break;
      }
      nextGcd = _gcd(currentGcd, count - k);
    }
  }

  _backtrack(0, 0);
  return result;
}

bool _isPrime(int n) {
  if (n < 2) {
    return false;
  }
  if (n == 2) {
    return true;
  }
  if (n % 2 == 0) {
    return false;
  }
  for (int i = 3; i * i <= n; i += 2) {
    if (n % i == 0) {
      return false;
    }
  }
  return true;
}

int _gcd(int a, int b) {
  while (b != 0) {
    final int temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

