/// Extended Euclidean Algorithm to find gcd(a, m) and integers x, y such that a*x + m*y = gcd(a, m)
/// Returns (g, x, y) where g is the gcd, x and y are coefficients
@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> extendedEuclidean(int a, int m) {
  int oldR = a, r = m;
  int oldS = 1, s = 0;
  int oldT = 0, t = 1;

  while (r != 0) {
    final q = oldR ~/ r;
    final tempR = oldR - q * r;
    oldR = oldR - q * r;
    r = r - q * tempR;

    final tempS = oldS - q * s;
    oldS = oldS - q * tempS;
    s = s - q * tempS;

    final tempT = oldT - q * t;
    oldT = oldT - q * tempT;
    t = t - q * tempT;
  }

  return [oldR, oldS, oldT];
}

