    while (lo <= hi && counts[lo + 1] > 0) {
      lo++;
    }
    while (lo <= hi && counts[hi] == 0) {
      hi--;
    }
    if (lo < hi) {
      int tmp = counts[lo];
      counts[lo] = counts[hi];
      counts[hi] = tmp;
    }
    lo++;
    hi--;
  }
  for (int r = 1; r <= 13; r++) {
