bool fn0(String log) {
  int parseSize(String s) {
    if (s == 'small') return 1;
    if (s == 'medium') return 2;
    if (s == 'large') return 3;
    return -1;
  }

  List<String> tokens = [];
  int i = 0;
  while (i < log.length) {
    if (log[i] == ' ') {
      i++;
      continue;
    }
    if (log[i] == ',' || log[i] == ';' || log[i] == '(' || log[i] == ')') {
      return false;
    }
    int start = i;
    while (i < log.length && log[i] != ' ' && log[i] != ',' && log[i] != ';' && log[i] != '(' && log[i] != ')') {
      i++;
    }
    tokens.add(log.substring(start, i));
  }

  if (tokens.length != 4) return false;
  if (tokens[0] != 'start' && tokens[0] != 'end') return false;

  int w1 = parseSize(tokens[1]);
  int h1 = parseSize(tokens[2]);
  int w2 = parseSize(tokens[3]);
  int h2 = parseSize(tokens[2]);

  if (w1 <= 0 || h1 <= 0 || w2 <= 0 || h2 <= 0) return false;

  int total = w1 * h1 + w2 * h2;
  int area = 0;

  for (int c1 = 0; c1 < w1; c1++) {
    for (int r1 = 0; r1 < h1; r1++) {
      bool covered = false;
      for (int c2 = 0; c2 < w2; c2++) {
        for (int r2 = 0; r2 < h2; r2++) {
          if (c1 + c2 == 1 && r1 + r2 == 1) {
            covered = true;
            break;
          }
        }
        if (covered) break;
      }
      if (!covered) area++;
    }
  }

  return area == total && area == 4;
}

