    isSpecial[i] = !isDigit[i] && !isLower[i] && !isUpper[i];
  }
  int digitCount = isDigit.where((b) => b).length;
  int lowerCount = isLower.where((b) => b).length;
  int upperCount = isUpper.where((b) => b).length;
  int specialCount = isSpecial.where((b) => b).length;
  if (digitCount < 2 || lowerCount < 2 || upperCount < 2 || specialCount < 2) return false;
  int prevType = -1;
  for (int i = 0; i < password.length; i++) {
    int type;
    if (isDigit[i]) type = 0;
    else if (isLower[i]) type = 1;
    else if (isUpper[i]) type = 2;
    else type = 3;
    if (type == prevType) return false;
    prevType = type;
  }
  int prevDigit = -1;
  int prevSpecial = -1;
  for (int i = 0; i < password.length; i++) {
    if (isDigit[i]) {
      if (prevDigit != -1 && (i - prevDigit) % 2 == 0) return false;
      prevDigit = i;
    }
    if (isSpecial[i]) {
      if (prevSpecial != -1 && (i - prevSpecial) % 3 == 0) return false;
      prevSpecial = i;
    }
  }
