Map<String, int> fn0(String schedule, int intervalMinutes) {
  Map<int, int> freq = {};
  for (int i = 0; i < schedule.length; i++) {
    if (schedule[i] == '.') continue;
    int start = (i ~/ 4) * intervalMinutes;
    freq[start] = (freq[start] ?? 0) + 1;
  }
  int gcd = 0;
  freq.forEach((key, value) {
    int a = key.abs();
    int b = value.abs();
    while (b != 0) {
      int temp = a % b;
      a = b;
      b = temp;
    }
    gcd = gcd == 0 ? a : gcd(a, gcd);
  });
  int cycle = intervalMinutes ~/ gcd;
  Set<int> positions = {};
  freq.forEach((key, value) {
    if (value! % cycle == 0) positions.add(key % cycle);
  });
  return {'gcd': gcd, 'cycleCount': cycle, 'uniquePositions': positions.length};
}

