@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> rows) {
  if (rows.isEmpty) return [];
  int cols = rows[0].length;
  if (cols == 0) return [];
  List<List<int>> dp = List.generate(rows.length, (_) => List.filled(cols, 0));
  for (int i = 0; i < rows.length; i++) {
    for (int j = 0; j < cols; j++) {
      if (rows[i][j] == '#') {
        dp[i][j] = 1;
        if (i > 0) dp[i][j] = dp[i][j] > dp[i - 1][j] ? dp[i][j] : dp[i - 1][j];
        if (j > 0) dp[i][j] = dp[i][j] > dp[i][j - 1] ? dp[i][j] : dp[i][j - 1];
      }
    }
  }
  int maxLen = dp[0][cols - 1];
  for (int i = 1; i < rows.length; i++) {
    if (dp[i][cols - 1] > maxLen) maxLen = dp[i][cols - 1];
  }
  List<String> result = [];
  void backtrack(int i, int j, int len, List<String> path) {
    if (len == 0) {
      result.add(path.join(','));
      return;
    }
    if (i > 0 && dp[i - 1][j] == len) {
      path.add('${i - 1},${j}');
      backtrack(i - 1, j, len - 1, path);
      path.removeLast();
    }
    if (j > 0 && dp[i][j - 1] == len) {
      path.add('${i},${j - 1}');
      backtrack(i, j - 1, len - 1, path);
      path.removeLast();
    }
  }
  for (int i = 0; i < rows.length; i++) {
    if (dp[i][cols - 1] == maxLen) {
      List<String> path = ['${i},${cols - 1}'];
      backtrack(i, cols - 1, maxLen - 1, path);
    }
  }
  result.sort();
  return result;
}

