double fn0(String schedule) {
  if (schedule.isEmpty) return 0.0;
  List<String> tokens = schedule.split(';');
  double totalMinutes = 0.0;
  int totalRuns = 0;
  int i = 0;
  while (i < tokens.length) {
    String token = tokens[i];
    int colon = token.lastIndexOf(':');
    if (colon <= 1 || colon == token.length - 1) {
      totalRuns++;
      i++;
      continue;
    }
    String body = token.substring(colon + 1);
    String suffix = body[body.length - 1];
    int multiplier = suffix == 'M' ? 1 : (suffix == 'H' ? 60 : (suffix == 'D' ? 1440 : 0));
    if (multiplier == 0) {
      totalRuns++;
      i++;
      continue;
    }
    String countStr = body.substring(0, body.length - 1);
    int count = int.tryParse(countStr) ?? 0;
    if (count > 0) {
      totalMinutes += count * multiplier;
      totalRuns++;
    }
    i++;
  }
  if (totalRuns == 0) return 0.0;
  return totalMinutes / totalRuns;
}

