  for (String token in encoded.split(',')) {
    if (token.isEmpty) continue;

    int dashIdx = token.indexOf('-');
    String countStr = token.substring(0, dashIdx);
    String itemStr = token.substring(dashIdx + 1);

    int count = int.parse(countStr);
    String item = itemStr;

    String lastChar = item.isEmpty ? 'B' : item[item.length - 1];
    int basePrice = 0;

    if (lastChar == 'B') {
      basePrice = 2;
    } else if (lastChar == 'C') {
      basePrice = 3;
    } else if (lastChar == 'D') {
      basePrice = 5;
    } else if (lastChar == 'M') {
      basePrice = 1;
    } else if (lastChar == 'P') {
      basePrice = 4;
    } else if (lastChar == 'R') {
      basePrice = 2;
    } else if (lastChar == 'S') {
      basePrice = 3;
    } else {
      basePrice = 0;
    }

    String rest = item.isEmpty ? '' : item.substring(0, item.length - 1);
    String firstChar = rest.isEmpty ? 'B' : rest[0];

    int modifier = 0;
    if (firstChar == 'M') {
      modifier = 1;
    } else if (firstChar == 'P') {
      modifier = -1;
    } else if (firstChar == 'S') {
      modifier = 2;
    } else if (firstChar == 'R') {
      modifier = -2;
    }

    double adjustedPrice = basePrice + modifier;

    double price;
    if (adjustedPrice < 0) {
      price = 0.0;
    } else if (adjustedPrice >= 1 && adjustedPrice < 2) {
      price = 1.0;
    } else if (adjustedPrice >= 2 && adjustedPrice < 3) {
      price = 2.0;
    } else if (adjustedPrice >= 3 && adjustedPrice < 4) {
      price = 3.0;
    } else if (adjustedPrice >= 4 && adjustedPrice < 5) {
      price = 4.0;
    } else {
      price = 5.0;
    }

    total += count * price;
  }

  return total;
}

