  List<String> tokens = schedule.split(' ');
  Map<String, double> seatPrices = {
    'A': 80.0,
    'B': 60.0,
    'C': 50.0,
    'D': 40.0,
    'M': 0.0,
    'P': 0.0,
    'R': 0.0,
    'S': 0.0
  };
  int totalMinutes = 0;
  double totalCost = 0.0;
  for (String token in tokens) {
    int colon = token.indexOf(':');
    if (colon <= 0) continue;
    String seat = token.substring(0, colon);
    String timePart = token.substring(colon + 1);
    int dash = timePart.indexOf('-');
    if (dash <= 0) continue;
    int start = int.parse(timePart.substring(0, dash));
    int end = int.parse(timePart.substring(dash + 1));
    if (end <= start) continue;
    totalMinutes += (end - start);
    double price = seatPrices[seat] ?? 0.0;
    if (seat == 'M') {
      price = price * 0.75;
    } else if (seat == 'P') {
      price = price * 1.25;
    } else if (seat == 'R') {
      price = price * 0.5;
    } else if (seat == 'S') {
      price = price * 0.25;
    }
    totalCost += price;
  }
  if (totalMinutes == 0) return 0.0;
  return totalCost / totalMinutes;
}

