double fn0(String signalSequence) {
  if (signalSequence.isEmpty) return 0.0;

  double getSignalScore(String sym) {
    switch (sym) {
      case 'B': return 0.0;
      case 'C': return 1.0;
      case 'D': return 2.0;
      case 'M': return 3.0;
      case 'P': return 4.0;
      case 'R': return 5.0;
      case 'S': return 6.0;
      default: return -1.0;
    }
  }

  double getSignalWeight(String sym) {
    switch (sym) {
      case 'B': return 0.1;
      case 'C': return 0.15;
      case 'D': return 0.2;
      case 'M': return 0.25;
      case 'P': return 0.3;
      case 'R': return 0.35;
      case 'S': return 0.4;
      default: return 0.0;
    }
  }

  int currentBase = 0;
  int currentSignalIndex = 0;
  double totalScore = 0.0;
  int validSignals = 0;
  int transitions = 0;
  int maxValidRun = 0;
  int currentRun = 0;
  int maxWeightedRun = 0;
  int currentWeightedRun = 0;

  while (currentSignalIndex < signalSequence.length) {
    String sym = signalSequence[currentSignalIndex];
    if (getSignalScore(sym) >= 0.0) {
      validSignals++;
      double score = getSignalScore(sym);
      double weight = getSignalWeight(sym);

      if (validSignals == 1) {
        currentBase = score;
      } else {
        if (score > currentBase) {
          transitions++;
        }
        currentBase = score;
      }

      if (score == 0.0) {
        currentRun = 0;
      } else {
        currentRun++;
        if (currentRun > maxValidRun) maxValidRun = currentRun;
      }

      double weightedScore = score * weight;
      if (weightedScore > currentWeightedRun) {
        currentWeightedRun = weightedScore.toInt();
      }

      totalScore += weightedScore;
      currentSignalIndex++;
    } else {
      if (validSignals > 0) {
        double avgWeighted = totalScore / validSignals;
        totalScore = avgWeighted * validSignals;
      }
      currentSignalIndex++;
    }
  }

  if (validSignals == 0) {
    return 0.0;
  }

  double score = totalScore / validSignals;
  double scoreComponent = score * 0.4;
  double transitionsComponent = transitions / 2.0 * 0.2;
  double runComponent = maxValidRun * 0.15;
  double weightedRunComponent = maxWeightedRun * 0.2;

  return scoreComponent - transitionsComponent + runComponent + weightedRunComponent;
}

