  List<String> tokens = stream.split(',');
  double score = 0.0;
  int maxLen = 0;
  int bestStart = -1;
  int bestEnd = -1;
  int n = tokens.length;
  List<int> dp = List.filled(n, 1);
  List<int> start = List.filled(n, 0);
  List<int> end = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    start[i] = i;
    end[i] = i;
  }
  for (int i = 1; i < n; i++) {
    if (tokens[i].startsWith(tokens[i - 1])) {
      dp[i] = dp[i - 1] + 1;
      start[i] = start[i - 1];
      end[i] = i;
    }
  }
  for (int i = 0; i < n; i++) {
    if (dp[i] > maxLen) {
      maxLen = dp[i];
      bestStart = start[i];
      bestEnd = end[i];
    }
  }
  String bestSeq = tokens.sublist(bestStart, bestEnd + 1).join(',');
  List<String> symbols = bestSeq.split('');
  int state = 0;
  int run = 0;
  int peaks = 0;
  String last = '';
  for (String ch in symbols) {
    if (state == 0) {
      if (ch == 'B' || ch == 'P' || ch == 'M') {
        state = 1;
        run = 1;
        last = ch;
      }
    } else if (state == 1) {
      if (ch == last) {
        run++;
      } else {
        if (ch == 'C' || ch == 'R' || ch == 'S') {
          state = 2;
        } else {
          state = 0;
        }
      }
    } else if (state == 2) {
      if (ch == 'D') {
        peaks++;
        state = 0;
        run = 0;
      } else {
        state = 0;
        run = 0;
      }
    }
  }
  if (peaks >= 2 && run >= 3) {
    score = maxLen * 1.5;
  } else if (peaks == 1 && run >= 2) {
    score = maxLen * 0.75;
  } else if (run >= 3) {
    score = maxLen * 0.5;
  }
  return score;
}

