Iterable<List<T>> combinations<T>(Iterable<T> elements, int k) sync* {
  if (k <= 0) yield [];
  if (elements.isEmpty) yield [];

  var elementsList = elements.toList();
  int n = elementsList.length;
  if (k > n) yield [];

  List<int> indices = List<int>.generate(k, (i) => i);

  while (true) {

    yield indices.map((i) => elementsList[i]).toList();

    int i = k - 1;
    while (i >= 0 && indices[i] == n - k + i) {
      i--;
    }

    if (i < 0) break; 

    indices[i] += 1;
    for (int j = i + 1; j < k; j++) {
      indices[j] = indices[j - 1] + 1;
    }
  }
}

