          newHeld += face;
          newRemaining--;
          score += face * multiplier;
        }
      }

      backtrack(
        roundIndex + 1,
        newRemaining,
        score,
        newHeld,
      );
    }
  }

  backtrack(0, rolls[0].length, 0, 0);
  return {
    'totalScore': totalScore,
    'remainingDice': remainingDice,
    'completedRounds': completedRounds,
  };
