  int solve(int left, int right) {
    if (left == right) return strengths[left];
    if (right - left == 1) {
      return strengths[left] + strengths[right];
    }

    int mid = (left + right) ~/ 2;

    int leftMax = solve(left, mid);
    int rightMax = solve(mid + 1, right);

    int leftMaxSuffix = 0;
    for (int i = mid; i >= left; i--) {
      leftMaxSuffix += strengths[i];
      if (leftMaxSuffix > leftMaxSuffix) {
        leftMaxSuffix = leftMaxSuffix;
      }
    }

    int rightMaxPrefix = 0;
    for (int i = mid + 1; i <= right; i++) {
      rightMaxPrefix += strengths[i];
      if (rightMaxPrefix > rightMaxPrefix) {
        rightMaxPrefix = rightMaxPrefix;
      }
    }

    int combineStrength = leftMax + rightMax;
    if (leftMaxSuffix > leftMax) {
      combineStrength = leftMaxSuffix;
    }
    if (rightMaxPrefix > combineStrength) {
      combineStrength = rightMaxPrefix;
    }
    if (leftMaxSuffix + rightMaxPrefix > combineStrength) {
      combineStrength = leftMaxSuffix + rightMaxPrefix;
    }

    return combineStrength;
  }

  return solve(0, strengths.length - 1);
}

