  int n = password.length;

  for (int i = 0; i < n; i++) {
    int code = password.codeUnitAt(i);
    int digitCount = 0;
    int letterCount = 0;

    while (code > 0) {
      int r = code % 10;
      if (r >= 48 && r <= 57) {
        digitCount++;
      } else if ((r >= 65 && r <= 90) || (r >= 97 && r <= 122)) {
        letterCount++;
      }
      code ~/= 10;
    }

    int digitSum = 0;
    int temp = code;
    while (temp > 0) {
      digitSum += temp % 10;
      temp ~/= 10;
    }

    if (digitCount >= 2 && letterCount == 0) {
      total += 1.0;
    } else if (digitCount == 1 && letterCount >= 2) {
      total += 0.5;
    } else if (digitCount == 1 && letterCount == 1) {
      total += 0.25;
    } else {
      total += 0.0;
    }

    int gcdVal = 0;
    int a = digitCount;
    int b = digitSum;
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    gcdVal = a;

    if (gcdVal == 1) {
      total += 0.25;
    } else {
      total -= 0.125;
    }
  }

  return total;
}

