Set<int> fn0(List<int> requests, int capacity) {
  int n = requests.length;
  if (n == 0 || capacity <= 0) {
    return <int>{};
  }

  int maxGap = 0;
  for (int i = 1; i < n; i++) {
    int gap = (requests[i] - requests[i - 1]).abs();
    if (gap > maxGap) {
      maxGap = gap;
    }
  }

  int left = 0;
  int right = 0;
  int covered = 0;

  while (left < n) {
    while (right < n && (requests[right] - requests[left]).abs() <= capacity) {
      covered += requests[right] - requests[left];
      right++;
    }

    int currentGap = maxGap;
    int minGap = int.maxValue;
    int minLeft = left;
    int minRight = left;
    int minCovered = covered;

    for (int i = left; i < right; i++) {
      int gap = (requests[i] - requests[left]).abs();
      if (gap < currentGap) {
        currentGap = gap;
        minGap = gap;
        minLeft = left;
        minRight = i;
        minCovered = covered;
      } else if (gap == currentGap) {
        int altCovered = covered - (requests[i] - requests[left]);
        int altLeft = left;
        int altRight = i;
        if (altCovered < minCovered) {
          minCovered = altCovered;
          minLeft = altLeft;
          minRight = altRight;
        }
      }
    }

    if (minGap < maxGap) {
      for (int i = minLeft; i <= minRight; i++) {
        if (i > minLeft) {
          return <int>{minLeft, i};
        }
      }
    }

    covered -= requests[right - 1] - requests[left];
    left++;
  }

  return <int>{left, n};
}

