      parent[i] = bestL;
      leftDist[i] = i - bestL;
      rightDist[i] = bestR - i;
    }
  }

  int maxLen = 0;
  int bestStart = 0, bestEnd = 0;
  int lastL = -1, lastR = -1;

  for (int i = 0; i < n; i++) {
