int fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  final rows = grid.length;
  final cols = grid[0].length;
  final visited = List.generate(rows, (_) => List.filled(cols, false));
  int count = 0;

  int floodFill(int r, int c, int target, int floodTarget) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return 0;
    if (grid[r][c] != target || visited[r][c]) return 0;
    visited[r][c] = true;
    int total = 1;
    final dirs = const [[0, 1], [1, 0], [0, -1], [-1, 0]];
    for (final d in dirs) {
      final nr = r + d[0];
      final nc = c + d[1];
      if (grid[nr][nc] == floodTarget) {
        total += floodFill(nr, nc, target, floodTarget);
      } else {
        total += floodFill(nr, nc, grid[nr][nc], target);
      }
    }
    return total;
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        final area = floodFill(r, c, grid[r][c], grid[r][c]);
        if (area >= 2) {
          count++;
        }
      }
    }
  }
  return count;
}

