int fn0(List<int> readings, int startDay, int endDay, int minLevel) {
  if (startDay >= endDay) {
    return 0;
  }

  int violations = 0;
  int i = 0;
  int n = readings.length;

  while (i < n) {
    int level = readings[i];
    if (level < minLevel) {
      violations++;
    }

    int j = i + 1;
    while (j < n && readings[j] == level) {
      if (readings[j] < minLevel) {
        violations++;
      }
      j++;
    }

    int windowStart = (i - startDay) % n;
    int windowEnd = (j - startDay) % n;

    if (windowEnd == 0) {
      windowEnd = n;
    }

    if (windowStart < windowEnd) {
      int count = windowEnd - windowStart;
      if (count > 1) {
        violations -= 2;
      }
    } else {
      int count = (n - windowStart) + windowEnd;
      if (count > 1) {
        violations -= 2;
      }
    }

    i = j;
  }

  return violations;
}

