int fn0(List<int> readings, int maxSkip) {
  int n = readings.length;
  if (n == 0) return 0;
  if (n <= 2) return 1;

  List<int> dp = List.filled(n, 1);

  for (int i = 2; i < n; i++) {
    int maxLen = 1;
    for (int j = i - 1; j >= 0; j--) {
      if (readings[i] >= readings[j]) break;
      int skipped = i - j;
      if (skipped > maxSkip) break;
      int lenThroughJ = dp[j] + 1;
      if (lenThroughJ > maxLen) {
        maxLen = lenThroughJ;
      }
    }
    dp[i] = maxLen;
  }

  return dp[n - 1];
}

