extension on Iterable<T> {
  Iterable<Set<T>> subsets() sync* {
    final list = this.toList();
    final n = list.length;
    for (int i = 1; i < (1 << n) - 1; i++) {
      final subset = <T>{};
      for (int j = 0; j < n; j++) {
        if ((i & (1 << j)) != 0) {
          subset.add(list[j]);
        }
      }
      if (subset.isNotEmpty) {
        yield subset;
      }
    }
  }
}

