    const List<List<int>> directions = <List<int>>[
      [-1, 0],
      [1, 0],
      [0, -1],
      [0, 1]
    ];

    for (List<int> delta in directions) {
      int nr = r + delta[0];
      int nc = c + delta[1];
      if (nr >= 0 &&
          nr < rows &&
          nc >= 0 &&
          nc < cols &&
          !current.contains(grid[nr][nc])) {
        dfs(nr, nc, List<int>.from(current));
      }
    }
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
