        int rightCost = grid[i][j + 1] <= 0 ? 0 : grid[i][j + 1];
        int right = (i > 0 ? dp[j + 1] : 1000000000) - rightCost;
        if (right < best) best = right;
      }
      nextDp[j] = best + cost;
    }
    dp = nextDp;
  }
