  for (final floor in requests) {
    if (floor > maxFloor) continue;
    if (visited[floor]) continue;
    visited[floor] = true;
    if (floor > current) {
      total += (floor - current) * up;
      switches.add(up);
    } else if (floor < current) {
      total += (current - floor) * down;
      switches.add(down);
    } else {
      total += 0 * stay;
      switches.add(stay);
    }
    current = floor;
  }
  if (switches.length <= 1) return total;
  final unique = <int>{};
  for (final s in switches) unique.add(s);
  final sorted = unique.toList()..sort();
  var result = 0;
  for (var i = 1; i < sorted.length; i++) {
    result += sorted[i] - sorted[i - 1];
  }
  return total + result;
}

