  int cols = grid[0].length;
  if (cols == 0) return false;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<int>> directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  int regions = 0;
  int totalOccupied = 0;

  bool isValid(int r, int c) {
    return r >= 0 && r < rows && c >= 0 && c < cols;
  }

  List<List<int>> queue = [];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] == 1 && !visited[r][c]) {
        regions++;
        visited[r][c] = true;
        queue.add([r, c]);
        int count = 0;
        while (queue.isNotEmpty) {
          List<int> current = queue.removeAt(0);
          int currR = current[0];
          int currC = current[1];
          count++;
          for (List<int> d in directions) {
            int nr = currR + d[0];
            int nc = currC + d[1];
            if (isValid(nr, nc) && grid[nr][nc] == 1 && !visited[nr][nc]) {
              visited[nr][nc] = true;
              queue.add([nr, nc]);
            }
          }
        }
        totalOccupied += count;
      }
    }
  }

  return regions >= minOccupied && totalOccupied >= minOccupied;
}

