  for (int shift = 0; shift <= resultSize; shift++) {
    int windowMask = (1 << resultSize) - 1;
    int shifted = occupiedMask >> shift;
    int windowed = shifted & windowMask;
    int pop = popCount(windowed);

    if (pop == 0) {
      if (resultIndex == -1 || shift < resultIndex) {
        resultIndex = shift;
      }
      continue;
    }

    int trailing = countTrailingZeros(windowed);
    bool isolated = true;
    int temp = windowed;

    while (temp > 0) {
      int bit = temp & -temp;
      int isolate = bit;
      int rest = temp ^ isolate;
      if (isolate != rest) {
        isolated = false;
        break;
      }
      temp = rest;
    }

    if (isolated) {
      if (pop < bestPop || (pop == bestPop && trailing < bestTrailing)) {
        bestPop = pop;
        bestTrailing = trailing;
        resultIndex = shift;
      }
    }
  }

  return {"size": resultSize, "index": resultIndex};
}

