class RTreeNode {
  final List<Point> points = [];
  List<RTreeNode?> children;
  final double minX, maxX, minY, maxY;
  final int maxPoints;

  RTreeNode(
    this.minX, this.maxX, this.minY, this.maxY, {
    this.maxPoints = 4,
  }) : children = List<RTreeNode?>.filled(4, null);

  void add(Point p) {
    if (p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY) {
      points.add(p);
      if (points.length > maxPoints) {
        _split();
      }
    }
  }

  void _split() {
    final dx = (maxX - minX) / 2;
    final dy = (maxY - minY) / 2;
    final midX = minX + dx;
    final midY = minY + dy;
    final regions = [
      RTreeNode(minX, midX, minY, midY, maxPoints: maxPoints),
      RTreeNode(midX, maxX, minY, midY, maxPoints: maxPoints),
      RTreeNode(minX, midX, midY, maxY, maxPoints: maxPoints),
      RTreeNode(midX, maxX, midY, maxY, maxPoints: maxPoints),
    ];
    for (final p in points) {
      for (final child in regions) {
        if (p.x >= child.minX && p.x <= child.maxX &&
            p.y >= child.minY && p.y <= child.maxY) {
          child.add(p);
          break;
        }
      }
    }
    children = regions;
    points.clear();
  }

  void query(double x1, double y1, double x2, double y2, List<Point> result) {
    if (x1 > x2 || y1 > y2) return;
    if (x1 < minX || x2 > maxX || y1 < minY || y2 > maxY) {
      _queryIntersecting(x1, y1, x2, y2, result);
    } else {
      for (final p in points) {
        if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
          result.add(p);
        }
      }
      if (children.isNotEmpty) {
        for (final child in children) {
          child?.query(x1, y1, x2, y2, result);
        }
      }
    }
  }

  void _queryIntersecting(double x1, double y1, double x2, double y2, List<Point> result) {
    final xs = [x1, x2, minX, maxX];
    final ys = [y1, y2, minY, maxY];
    final xMin = xs.reduce(math.min);
    final xMax = xs.reduce(math.max);
    final yMin = ys.reduce(math.min);
    final yMax = ys.reduce(math.max);
    for (final p in points) {
      if (p.x >= xMin && p.x <= xMax && p.y >= yMin && p.y <= yMax) {
        result.add(p);
      }
    }
    if (children.isNotEmpty) {
      for (final child in children) {
        child?.query(x1, y1, x2, y2, result);
      }
    }
  }
}

