bool pointInCircle(Point point, Range range) {
  final dx = point.x - range.center.x;
  final dy = point.y - range.center.y;
  return dx * dx + dy * dy <= range.radius * range.radius;
}

List<Point> findPointsInRange(List<Point> points, Range range) {
  return points.where((point) => pointInCircle(point, range)).toList();
}

