List<int> fn0(List<int> deck, int maxGap) {
  if (deck.isEmpty) {
    return <int>[];
  }
  final int rankCount = deck.length;
  final List<int> deckCopy = List<int>.from(deck);
  final List<int> counts = List<int>.filled(13, 0);
  for (final int rank in deckCopy) {
    if (rank >= 0 && rank < 13) {
      counts[rank]++;
    }
  }
  int left = 0;
  int minCount = rankCount + 1;
  int bestStart = 0;
  int bestEnd = rankCount;
  int bestSum = 0;
  for (int right = 0; right < 13; right++) {
    if (counts[right] > 0) {
      while (left <= right &&
              (left == right || deckCopy[left] > deckCopy[right] + maxGap)) {
        if (counts[deckCopy[left]] == 1) {
          if (counts[deckCopy[left]] < minCount) {
            minCount = counts[deckCopy[left]];
          }
        }
        left++;
      }
      if (left > right) {
        left = right + 1;
      }
    }
    if (counts[right] > 0) {
      final int windowLen = right - left + 1;
      if (windowLen < bestEnd - bestStart) {
        bestStart = left;
        bestEnd = right;
        bestSum = windowLen;
      } else if (windowLen == bestEnd - bestStart) {
        if (counts[deckCopy[bestStart]] > counts[deckCopy[left]]) {
          bestStart = left;
          bestEnd = right;
          bestSum = windowLen;
        }
      }
    }
  }
  final List<int> result = <int>[];
  for (int i = bestStart; i <= bestEnd; i++) {
    if (counts[i] > 0) {
      result.add(i);
    }
  }
  return result;
}

