String fn0(double weightOnEarth, List<String> moonDays) {
  double moonWeight = weightOnEarth * 0.165;
  double totalMoonWeight = 0.0;
  double maxMoonWeight = double.negativeInfinity;
  double minMoonWeight = double.infinity;
  for (String day in moonDays) {
    List<String> parts = day.split(':');
    int hour = int.parse(parts[0]);
    int minute = int.parse(parts[1]);
    int second = int.parse(parts[2]);
    int microsecond = int.parse(parts[3]);
    double multiplier = 0.0;
    if (hour >= 0 && hour < 6) {
      multiplier = 0.1;
    } else if (hour >= 6 && hour < 12) {
      multiplier = 0.2;
    } else if (hour >= 12 && hour < 18) {
      multiplier = 0.3;
    } else if (hour >= 18 && hour < 24) {
      multiplier = 0.4;
    }
    double adjustment = (minute + second / 60 + microsecond / 1_000_000) / 60.0;
    double dayMultiplier = multiplier + adjustment;
    double dayWeight = moonWeight * dayMultiplier;
    totalMoonWeight += dayWeight;
    if (dayWeight > maxMoonWeight) {
      maxMoonWeight = dayWeight;
    }
    if (dayWeight < minMoonWeight) {
      minMoonWeight = dayWeight;
    }
  }
  double average = totalMoonWeight / moonDays.length;
  if (average.isNaN) {
    return 'On the Moon, you would weigh NaN kg';
  }
  double rounded = (average * 2).round() / 2.0;
  return 'On the Moon, you would weigh $rounded kg (max: $maxMoonWeight kg, min: $minMoonWeight kg)';
}

