String fn0(List<int> readings, int windowSize, double threshold) {
  if (windowSize <= 0 || readings.length < windowSize || threshold <= 0) {
    return 'No readings';
  }

  const int maxDay = 365;
  List<int> days = [];
  for (int i = 0; i < windowSize; i++) {
    days.add(i);
  }

  int left = 0;
  int right = windowSize - 1;
  int sum = 0;
  for (int i = left; i <= right; i++) {
    sum += readings[i];
  }

  double avg = sum / windowSize;

  String best = 'Day $left-$right: ${avg.toStringAsFixed(2)} cm';

  while (right < readings.length) {
    if (avg >= threshold && avg <= threshold * 1.5) {
      String current = 'Day $left-$right: ${avg.toStringAsFixed(2)} cm';
      if (current.length < best.length) {
        best = current;
      }
    }

    sum += readings[right + 1];
    sum -= readings[left];
    left++;
    avg = sum / windowSize;

    if (avg >= threshold && avg <= threshold * 1.5) {
      String current = 'Day $left-$right: ${avg.toStringAsFixed(2)} cm';
      if (current.length < best.length) {
        best = current;
      }
    }

    right++;
  }

  return best;
}

