    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  int k = 2; 
  int maxIterations = 100;
  double tolerance = 1e-4;

  List<List<double>> centroids = [];
  Random rand = Random(0);

  for (int i = 0; i < k; i++) {
    centroids.add([
      rand.nextDouble() * 10 - 5, 
      rand.nextDouble() * 10 - 5,
    ]);
  }

  List<int> labels = List.filled(data.length, 0);
  List<List<double>> clusters = List.generate(k, (_) => []);

  bool converged = false;
  int iteration = 0;

  while (iteration < maxIterations && !converged) {
    converged = true;

    for (int i = 0; i < data.length; i++) {
      double minDist = double.infinity;
      int bestLabel = 0;

      for (int c = 0; c < k; c++) {
        double dist = (data[i][0] - centroids[c][0]).abs() +
            (data[i][1] - centroids[c][1]).abs();
        if (dist < minDist) {
          minDist = dist;
          bestLabel = c;
        }
      }

      if (labels[i] != bestLabel) {
        converged = false;
      }
      labels[i] = bestLabel;
      clusters[bestLabel].add(data[i]);
    }

    List<List<double>> newCentroids = List.generate(k, (_) => [0.0, 0.0]);
    List<int> counts = List.filled(k, 0);

    for (int c = 0; c < k; c++) {
      List<double> cluster = clusters[c];
      if (cluster.isEmpty) {
        newCentroids[c] = [0.0, 0.0];
        counts[c] = 1;
      } else {
        double sumX = 0.0, sumY = 0.0;
        for (var point in cluster) {
          sumX += point[0];
          sumY += point[1];
        }
        newCentroids[c] = [sumX / cluster.length, sumY / cluster.length];
        counts[c] = cluster.length;
      }
    }

    for (int c = 0; c < k; c++) {
      double dx = newCentroids[c][0] - centroids[c][0];
      double dy = newCentroids[c][1] - centroids[c][1];
      if (dx.abs() > tolerance || dy.abs() > tolerance) {
        converged = false;
      }
      centroids[c] = [newCentroids[c][0], newCentroids[c][1]];
    }

    iteration++;
  }

  print('Cluster centroids:');
  for (int c = 0; c < k; c++) {
    print('Cluster $c: centroid: ${centroids[c]}');
  }

  print('\nConverged in $iteration iteration(s).');

  for (int c = 0; c < k; c++) {
    print('Cluster $c: Points ${clusters[c].map((p) => '${p[0]}, ${p[1]}').join(', ')}');
