    centroids.add(data[i % n]);
  }

  double lastSumOfDistances = double.infinity;
  int iteration = 0;

  while (iteration < maxIterations) {
    bool changed = false;

    for (int i = 0; i < n; i++) {
      double minDistance = double.infinity;
      int bestCluster = -1;

      for (int j = 0; j < k; j++) {
        double distance = 0;
