    'maxSegmentLength': 0,
    'maxSegmentScore': 0,
    'minSegmentLength': 999999,
  };

  int rows = grid.length;
  int cols = grid[0].length;
  int passable = 0;
  int segments = 0;
  int maxLen = 0;
  int maxScore = -999999;
  int minLen = 999999;

  List<List<int>> visited = List.generate(rows, (_) => List.filled(cols, 0));

  bool isValid(int r, int c) {
    return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c][2] >= 50;
  }

  void dfs(int r, int c, int score, int depth) {
    if (visited[r][c] == 1) return;
    visited[r][c] = 1;
    passable++;
    if (score > maxScore) maxScore = score;
    if (depth > maxLen) maxLen = depth;
    if (depth < minLen) minLen = depth;

    int maxH = grid[r][c][0];
    int maxW = grid[r][c][1];

    List<List<int>> next = [];
    if (r + maxH < rows && grid[r + maxH][c][2] >= 50) next.add([r + maxH, c]);
    if (r - maxH >= 0 && grid[r - maxH][c][2] >= 50) next.add([r - maxH, c]);
    if (c + maxW < cols && grid[r][c + maxW][2] >= 50) next.add([r, c + maxW]);
    if (c - maxW >= 0 && grid[r][c - maxW][2] >= 50) next.add([r, c - maxW]);

    for (var nd in next) {
      dfs(nd[0], nd[1], score + grid[nd[0]][nd[1]][3], depth + 1);
    }
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c][2] >= 50 && visited[r][c] == 0) {
        dfs(r, c, grid[r][c][3], 1);
        segments++;
      }
    }
  }

  return {
    'totalPassableCells': passable,
    'segmentCount': segments,
    'maxSegmentLength': maxLen,
    'maxSegmentScore': maxScore,
    'minSegmentLength': minLen,
  };
