      int count = 0;
      bool hasCenter = false;
      bool hasEdge = false;
      List<List<int>> queue = [[r, c]];
      visited[r][c] = true;
      while (queue.isNotEmpty) {
        List<int> curr = queue.removeAt(0);
        int currR = curr[0], currC = curr[1];
        if (currR == r && currC == c) hasCenter = true;
        if (currR == 0 || currR == rows - 1 || currC == 0 || currC == cols - 1) hasEdge = true;
        count++;
        for (var dir in directions) {
          int nr = currR + dir[0], nc = currC + dir[1];
          if (isValid(nr, nc)) {
            visited[nr][nc] = true;
            queue.add([nr, nc]);
          }
        }
      }
      if (!hasCenter || hasEdge || count < 5) return false;
    }
  }
  return true;
}

