        if (letters.contains(code[i])) {
          score = score! * 26 + codePoint - 65;
        } else if (digits.contains(code[i])) {
          state = 1;
        }
      }
    }
    if (state >= 2 && score != null) {
      if (code.length <= maxLen && code.length >= minScore) {
        valid.add(code);
      }
    }
  }
  return valid.isNotEmpty;
}

