int fn0(String grid) {
  int count = 0;
  int rows = grid.length;
  if (rows == 0) return 0;
  int cols = grid[0].length;
  if (cols == 0) return 0;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      String cell = grid[r][c];
      if (cell != 'W') continue;

      bool isEdge = (r == 0 || r == rows - 1 || c == 0 || c == cols - 1);
      bool hasBWNeighbor = false;

      for (int dr = -1; dr <= 1; dr++) {
        for (int dc = -1; dc <= 1; dc++) {
          if (dr == 0 && dc == 0) continue;
          int nr = r + dr;
          int nc = c + dc;

          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
            String neighbor = grid[nr][nc];
            if (neighbor != 'W') {
              hasBWNeighbor = true;
              break;
            }
          }
        }
        if (hasBWNeighbor) break;
      }

      if (isEdge && hasBWNeighbor) {
        count++;
      }
    }
  }
  return count;
}

