  int index = 0;
  int? previousX;
  int? previousY;

  while (index < encoded.length) {
    int codeUnit = encoded.codeUnitAt(index);

    if (codeUnit < 48 || codeUnit > 57) {
      return false;
    }

    int start = index;
    while (index < encoded.length) {
      int c = encoded.codeUnitAt(index);
      if (c < 48 || c > 57) {
        break;
      }
      index++;
    }

    int count = int.parse(encoded.substring(start, index));
    int distance = count + 2;

    if (previousX != null && previousY != null) {
      currentWeight += distance;
    }

    index++;

    if (index >= encoded.length) {
      return false;
    }

    codeUnit = encoded.codeUnitAt(index);

    if (codeUnit < 97 || codeUnit > 122) {
      return false;
    }

    previousX = index;

    index++;
    previousY = index;

    if (index >= encoded.length) {
      return false;
    }

    codeUnit = encoded.codeUnitAt(index);

    if (codeUnit < 97 || codeUnit > 122) {
      return false;
    }

    index++;

    if (previousX == null || previousY == null) {
      return false;
    }

    String file1 = encoded.substring(previousX!, previousY!);
    String file2 = encoded.substring(index - 1);

    if (file1.length != 1 || file2.length != 1) {
      return false;
    }

    int file1Index = file1.codeUnitAt(0) - 96;
    int file2Index = file2.codeUnitAt(0) - 96;

    if (file1Index < 1 || file1Index > 8 || file2Index < 1 || file2Index > 8) {
      return false;
    }

    int rank1 = previousX - file1Index;
    int rank2 = index - 1 - file2Index;

    if (rank1 < 1 || rank1 > 8 || rank2 < 1 || rank2 > 8) {
      return false;
    }

    if (rank1 != rank2) {
      return false;
    }

    if (file1Index == file2Index) {
      return false;
    }

    int fileDistance = (file1Index - file2Index).abs();
    int actualDistance = (rank1 - rank2).abs() + fileDistance;

    if (distance != actualDistance) {
      return false;
    }

    previousX = index - 1;
    previousY = index;
    index++;
  }

  return currentWeight == expectedWeight;
}

