Set<int> fn0(List<int> signalMasks) {
  if (signalMasks.isEmpty) {
    return <int>{};
  }

  List<int> sorted = List<int>.from(signalMasks);
  sorted.sort((int a, int b) {
    int popA = _popcount(a);
    int popB = _popcount(b);
    if (popA != popB) {
      return popB.compareTo(popA);
    }
    int weightA = _bitWeight(a);
    int weightB = _bitWeight(b);
    if (weightA != weightB) {
      return weightA.compareTo(weightB);
    }
    return a.compareTo(b);
  });

  Set<int> result = <int>{};
  for (int i = 0; i < sorted.length; i++) {
    int value = sorted[i];
    if (i == 0 ||
        _popcount(value) != _popcount(sorted[i - 1]) ||
        _bitWeight(value) != _bitWeight(sorted[i - 1])) {
      result.add(value);
    }
  }

  return result;
}

int _popcount(int value) {
  int count = 0;
  while (value != 0) {
    count += value & 1;
    value >>= 1;
  }
  return count;
}

int _bitWeight(int value) {
  int weight = 0;
  int temp = value;
  while (temp != 0) {
    weight += 32 - (temp.toString(2).length);
    temp &= temp - 1;
  }
  return weight;
}

