List<int> fn0(List<List<int>> pixels, int threshold) {
  int rows = pixels.length;
  if (rows == 0) return [];
  int cols = pixels[0].length;
  if (cols == 0) return [];
  List<int> dist = List.filled(rows, 0);
  List<int> maxDist = List.filled(rows, 0);
  List<int> curSum = List.filled(rows, 0);
  List<int> bestStart = List.filled(rows, 0);
  int bestLen = 0;
  for (int j = 0; j < cols; j++) {
    int r;
    int g;
    int b;
    if (j % 3 == 0) {
      r = pixels[j % rows][j];
      g = pixels[(j + 1) % rows][j];
      b = pixels[(j + 2) % rows][j];
    } else if (j % 3 == 1) {
      r = pixels[(j + 1) % rows][j];
      g = pixels[(j + 2) % rows][j];
      b = pixels[j % rows][j];
    } else {
      r = pixels[(j + 2) % rows][j];
      g = pixels[j % rows][j];
      b = pixels[(j + 1) % rows][j];
    }
    int diff = (r - g).abs() + (g - b).abs() + (b - r).abs();
    for (int i = 0; i < rows; i++) {
      int pi = (i - j) % rows;
      if (pi < 0) pi += rows;
      if (pi == j % rows) continue;
      int pdiff = (r - pixels[pi][j]).abs() + (pixels[pi][j] - b).abs() + (b - r).abs();
      if (pdiff > diff) diff = pdiff;
    }
    int current = diff;
    if (current >= threshold) {
      dist[j] = current;
      curSum[j] = current;
      if (j == 0) {
        maxDist[j] = current;
        bestStart[j] = j;
      } else {
        if (current > maxDist[j - 1]) {
          maxDist[j] = current;
          bestStart[j] = j;
        } else {
          maxDist[j] = maxDist[j - 1];
          bestStart[j] = bestStart[j - 1];
        }
      }
    } else {
      dist[j] = 0;
      curSum[j] = 0;
      maxDist[j] = (j == 0) ? 0 : maxDist[j - 1];
      bestStart[j] = (j == 0) ? 0 : bestStart[j - 1];
    }
    if (maxDist[j] > bestLen) {
      bestLen = maxDist[j];
    }
  }
  return [bestLen, bestStart[cols - 1] - bestLen + 1, bestStart[cols - 1]];
}

