  if (n == 0) return 0;

  List<int> dp = List.filled(n + 1, 0);
  List<int> maxLen = List.filled(n + 1, 1);
  List<int> bestStart = List.filled(n + 1, 0);

  for (int i = 1; i <= n; i++) {
    int bestLen = 1;
    int bestStartIdx = 0;
    for (int j = 1; j < i; j++) {
      if (readings[i - 1] - readings[j - 1] <= maxDeviation) {
        int candidateLen = dp[j] + 1;
        if (candidateLen > bestLen) {
          bestLen = candidateLen;
          bestStartIdx = j;
        }
      }
    }
    dp[i] = bestLen;
    maxLen[i] = bestLen;
    bestStart[i] = bestStartIdx;
  }

  int globalMaxLen = 1;
  int globalStart = 0;
  for (int i = 1; i <= n; i++) {
    if (maxLen[i] > globalMaxLen) {
      globalMaxLen = maxLen[i];
      globalStart = bestStart[i];
    }
  }

  return globalMaxLen;
}

