  if (rows == 0) return true;
  int cols = grid[0].length;
  if (cols == 0) return true;
  if (rows < 3 || cols < 3) return false;
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<int>> queue = [[0, 0]];
  visited[0][0] = true;
  bool hasCenter = false;
  List<List<int>> dist = List.generate(rows, (_) => List.filled(cols, -1));
  dist[0][0] = 0;
  int head = 0;
  while (head < queue.length) {
    List<int> cur = queue[head++];
    int r = cur[0], c = cur[1];
    if (r == rows - 1 && c == cols - 1) {
      if (!hasCenter) return false;
      int d = dist[r][c];
      if (d != dist[rows ~/ 2][cols ~/ 2]) return false;
      return true;
    }
    for (List<int> dr in [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
      int nr = r + dr[0], nc = c + dr[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
        if (grid[nr][nc] == '.') {
          visited[nr][nc] = true;
          queue.add([nr, nc]);
          dist[nr][nc] = dist[r][c] + 1;
        } else {
          if (nr == rows ~/ 2 && nc == cols ~/ 2) hasCenter = true;
        }
      }
    }
  }
  return false;
}

