List<int> fn0(List<int> quantities, int base, int maxGap) {
  if (quantities.isEmpty) {
    return <int>[];
  }

  int g = quantities[0].abs();
  for (int i = 1; i < quantities.length; i++) {
    int q = quantities[i].abs();
    while (q != 0) {
      int t = g % q;
      g = q;
      q = t;
    }
  }

  List<int> result = <int>[];
  int n = quantities.length;
  List<int> mods = <int>[];
  List<int> vals = <int>[];

  for (int q in quantities) {
    int a = q ~/ g;
    int r = q % g;
    if (r == 0) {
      a = base;
    } else if (a < 0) {
      a = -a;
    }
    int m = a % base;
    if (m == 0) {
      m = base;
    }
    mods.add(m);
    vals.add(a);
  }

  int gcd = mods[0];
  for (int i = 1; i < mods.length; i++) {
    int a = gcd;
    int b = mods[i];
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    gcd = a;
  }

  List<int> unique = <int>[];
  for (int i = 0; i < n; i++) {
    if (mods[i] % gcd == 1) {
      unique.add(vals[i]);
    }
  }

  if (unique.isEmpty) {
    return result;
  }

  int limit = 1;
  while (limit < maxGap) {
    limit *= base;
  }

  for (int m = 1; m <= limit; m++) {
    bool ok = true;
    for (int v in unique) {
      if ((v * m) % base != 1) {
        ok = false;
        break;
      }
    }
    if (ok) {
      result.add(m);
    }
  }

  result.sort();
  return result;
}

