int fn0(List<int> playlist, int start, int duration) {
  if (start < 0) return -1;
  if (start + duration > playlist.length) return -1;
  if (duration <= 0) return -1;

  final counts = <int, int>{};
  int maxCount = 0;
  int firstArtist = -1;
  int bestStart = -1;

  for (int i = start; i < start + duration; i++) {
    final artist = playlist[i];
    counts[artist] = (counts[artist] ?? 0) + 1;
    if (counts[artist]! > maxCount) {
      maxCount = counts[artist]!;
      firstArtist = artist;
      bestStart = i - maxCount + 1;
    }
  }

  int? bestEnd;
  for (int end = start + duration - 1; end >= start; end--) {
    final artist = playlist[end];
    counts[artist] = (counts[artist] ?? 0) - 1;
    if (counts[artist] == 0) {
      counts.remove(artist);
    }
    if (counts.length == maxCount) {
      bestEnd = end;
      break;
    }
  }

  if (bestEnd == null) return -1;
  return bestStart + bestEnd;
}

