Set<int> fn0(List<int> sortedPrices, int target) {
  Set<int> result = {};
  int left = 0;
  int right = sortedPrices.length - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedPrices[mid] == target) {
      result.add(mid);
      int idx = mid - 1;
      while (idx >= 0 && sortedPrices[idx] == target) {
        result.add(idx);
        idx--;
      }
      idx = mid + 1;
      while (idx < sortedPrices.length && sortedPrices[idx] == target) {
        result.add(idx);
        idx++;
      }
      left = mid + 1;
    } else if (sortedPrices[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return result;
}

