List<int> fn0(List<int> rolls, int targetSum) {
  List<int> backtracking(int start, int remaining) {
    if (remaining == 0) return [start];
    List<int> paths = [];
    for (int i = start; i < rolls.length; i++) {
      int newRemaining = remaining - rolls[i];
      if (newRemaining >= 0) {
        List<int> subpaths = backtracking(i + 1, newRemaining);
        for (int path in subpaths) {
          paths.add(path);
        }
      }
    }
    return paths;
  }
  return backtracking(0, targetSum);
}

